from rest_framework.decorators import api_view, permission_classes
from rest_framework.permissions import IsAuthenticated
from rest_framework.response import Response
from django.shortcuts import get_object_or_404
from .models import DeveloperWebhookConfig

@api_view(['GET'])
@permission_classes([IsAuthenticated])
def reveal_webhook_secret(request, endpoint_id):
    # Enforce developer account ownership
    webhook = get_object_or_404(
        DeveloperWebhookConfig,
        id=endpoint_id,
        developer_account=request.user.developer_account
    )

    return Response({
        "endpoint_id": webhook.id,
        "target_url": webhook.target_url,
        "hmac_signing_secret": webhook.encrypted_signing_secret
    })
